const items = $input.all();
const data = $('Load Queued Messages from Queue Sheet');
const sheet_id = data.item.json.sheet_id ?? '';
// Referenced directly from the queue read (not the splitInBatches loop node)
// and coerced to '' instead of left undefined -- when this evaluated to
// undefined, the resulting json object never had a row_number KEY at all
// (JS/JSON serialization drops undefined-valued keys entirely), and since
// the sheet's header already reserves a column for it, autoMapInputData
// wrote fromEmail's value into the row_number cell instead and shifted
// every field after it one column left. Same fix as the Gmail processor.
const row_number = data.item.json.row_number ?? '';
// logged-in mailbox email
const MY_EMAIL = 'jack@marblebee.com'.toLowerCase();

/**
 * Cut message at polite sign-offs like "Kind regards,"
 */
function cutAtKindRegards(text = '') {
  const match = text.match(
    /\b(Kind regards|Best regards|Regards|Warm regards),\b/i
  );
  return match ? text.slice(0, match.index).trim() : text.trim();
}

/**
 * Extract latest message from Outlook/Gmail HTML body
 */
function extractLatestMessageFromHtml(html = '') {
  if (!html) return '';

  // Remove scripts & styles
  html = html
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '');

  // Cut at known reply/forward separators (earliest match wins)
  const cutPatterns = [
    /<hr[\s\S]*?>/i,
    /<div[^>]+id=["']divRplyFwdMsg["'][\s\S]*?>/i,
    /<div[^>]+class=["'][^"']*gmail_quote[^"']*["'][\s\S]*?>/i,
    /\nOn\s+(Mon|Tue|Wed|Thu|Fri|Sat|Sun),\s+[A-Za-z]{3}\s+\d{1,2},\s+\d{4},/i
  ];

  for (const pattern of cutPatterns) {
    const match = html.match(pattern);
    if (match) {
      html = html.slice(0, match.index);
    }
  }

  // Strip remaining HTML -> plain text
  return html
    .replace(/<\/?[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}


function cutAtReplyDate(text = '') {
  const replyRegex =
    /\nOn\s+(Mon|Tue|Wed|Thu|Fri|Sat|Sun),\s+[A-Za-z]{3}\s+\d{1,2},\s+\d{4},\s+\d{1,2}:\d{2}\s*(AM|PM)/i;

  const match = text.match(replyRegex);
  return match ? text.slice(0, match.index).trim() : text.trim();
}

/**
 * Strip HTML safely
 */
function stripHtml(html = '') {
  return html
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<\/?[^>]+(>|$)/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Cut text at first occurrence of:
 *  - 5 or more underscores
 *  - "Get Outlook for "
 * whichever comes first
 */
function cutAtSeparator(text = '') {
  const match = text.match(/_{5,}|Get Outlook for /i);
  return match ? text.slice(0, match.index).trim() : text.trim();
}

return items.map((item, index) => {
  const msg = item.json;

  // sender
  const fromEmail =
    msg.from?.emailAddress?.address || null;
  const fromName =
    msg.from?.emailAddress?.name || null;

  // receivers -- joined into a plain comma-separated string, matching the
  // Gmail processor's convention for this shared sheet (this used to be a
  // raw array, which stringified into the cell as e.g. ["a@b.com"] instead
  // of a clean address).
  const toRecipientsArr = msg.toRecipients || [];
  const toEmail =
    toRecipientsArr.map(r => r.emailAddress?.address).filter(Boolean).join(', ') || null;
  const toName =
    toRecipientsArr.map(r => r.emailAddress?.name).filter(Boolean).join(', ') || null;

  // sent or received -- uppercase to match the Gmail processor's convention;
  // a client's conversation sheet interleaves both providers, so the two
  // must agree on casing.
  const direction =
    fromEmail?.toLowerCase() === MY_EMAIL
      ? 'SENT'
      : 'RECEIVED';

  // body (HTML -> text)
let message = '';

if (msg.body?.contentType === 'html') {
  message = extractLatestMessageFromHtml(msg.body.content);
} else {
  message = stripHtml(msg.body?.content || '');
}

// Remove signatures / Outlook footer
message = cutAtSeparator(message);

// Remove quoted reply thread
message = cutAtReplyDate(message);

// Remove content after "Kind regards,"
message = cutAtKindRegards(message);


  return {
    json: {
      id: msg.id ?? '',
      sheet_id,
      row_number,
      message,
      fromEmail,
      fromName,
      toEmail,
      toName,
      direction,
      timestamp:
        msg.sentDateTime || msg.receivedDateTime,
      subject: msg.subject || null,
      hasAttachments: msg.hasAttachments || false
    },

    binary: $input.all()[index]?.binary || {}
  };
});

// Each conversation sheet is created via the Sheets API with an explicit
// sheets[] array and no sheetId specified -- per Google's own docs, an
// unspecified sheetId is RANDOMLY GENERATED, not 0, and the tab name itself
// is also inconsistent across sheets ('sheet1' vs 'Sheet1'). Neither a
// hardcoded name nor a hardcoded gid can address it. Look up this specific
// document's actual (single) tab name at runtime and reference it by name
// from here on -- same fix as the Gmail processor.
const original = $('Normalize | Extract Message Metadata').item;
const tabName = $json.sheets?.[0]?.properties?.title;
if (!tabName) {
  throw new Error(`Could not resolve the conversation sheet's tab name for sheet_id ${original.json.sheet_id}`);
}
return [{
  json: { ...original.json, tabName },
  binary: original.binary
}];

// The lookup node above replaces our data with whatever row it found (or
// {} via Always Output Data if nothing matched, or an {error: ...} shaped
// item if the sheet is missing a filtered-on column) -- recover the real
// message data (and its binary attachments) from before the lookup, and
// just carry forward whether a real row was found.
//
// 'row_number' is NOT the found-signal here (this sheet may not even have
// that column). Use the Sheets node's own always-attached 'row_number'
// metadata field instead -- present on every real matched row regardless
// of which actual columns that row has. Matching is done on timestamp +
// fromEmail + toEmail + subject (see the lookup node) since those columns
// exist on every row ever logged, old and new, by either provider.
const lookupResult = $input.first().json;
const original = $('Extract Tab Name').item;
return [{
  json: { ...original.json, _alreadyLogged: !!(lookupResult && lookupResult.row_number !== undefined) },
  binary: original.binary
}];

const items = $input.all();
const newItems = [];

items.forEach((item, itemIndex) => {
    const jsonData = item.json || {};
    const binaries = item.binary || {};

    let index = 0;
    for (const key in binaries) {
        // Get the original filename if available
        const originalFileName = binaries[key].fileName || key;
        const binaryKey = `attachment_${index}`;

        newItems.push({
            json: {
                ...jsonData,
                file_name: originalFileName,
                binary_field_name: binaryKey // <-- added field name of binary
            },
            binary: {
                [binaryKey]: binaries[key]
            },
            // This fans one email out into N attachment items -- without
            // pairedItem, n8n loses the lineage back to that source item,
            // and every downstream $('SomeNode').item lookup (the Message
            // Already Logged? read in Merge | Add Drive Links, the Loop |
            // Outlook Message IDs subf5_id read in the Drive nodes) throws
            // "Cannot read properties of undefined (reading 'pairedItem')"
            // for any email that actually has an attachment.
            pairedItem: itemIndex
        });
        index++;
    }
});

return newItems;

// One item per attachment goes into the search above, but Drive can
// return 0, 1, or several loosely-matched candidates per attachment --
// group results back by which original attachment they belong to
// (pairedItem), then pick the exact filename match (if any) within
// that attachment's own group. Guarantees exactly one output item per
// original attachment, in the same order, never mixing one
// attachment's candidates into another's decision.
//
// Preserve the ORIGINAL item's json (file_name, binary_field_name, ...)
// and binary data untouched, just annotated with the match result --
// 'Drive | Upload Attachment' (the not-found path) needs that original
// binary/file_name to actually upload; overwriting the item with just
// {id, name} would silently break every real upload.
const originals = $('Expand | Split Attachments').all();
const candidates = $input.all();

// Track each candidate's own ARRAY POSITION in `candidates` (this node's
// real $input), not just which attachment it belongs to. pairedItem must
// point at a real index into this node's own input for n8n to keep the
// lineage chain unbroken -- using the attachment's index instead (0, 1, 2..)
// breaks the moment any earlier attachment returns more than one candidate
// (search node's 'Drive | Find Existing Attachment' has alwaysOutputData on
// so every attachment adds at least one, but not always exactly one, entry
// to this flat list), which shifts every later attachment's true position
// out from under that naive index and corrupts the chain downstream --
// every $('SomeNode').item lookup after this node (the message-metadata
// read in 'Merge | Add Drive Links', the folder id read in 'Drive | Upload
// Attachment') then throws "Cannot read properties of undefined (reading
// 'pairedItem')" for any email whose attachment search fanned out.
const byOrigin = new Map();
candidates.forEach((c, candidateIndex) => {
  const idx = typeof c.pairedItem === 'number' ? c.pairedItem : c.pairedItem?.item;
  if (idx === undefined) return;
  if (!byOrigin.has(idx)) byOrigin.set(idx, { items: [], firstCandidateIndex: candidateIndex });
  byOrigin.get(idx).items.push(c);
});

return originals.map((orig, idx) => {
  const expected = (orig.json.file_name || '').toString().trim().toLowerCase();
  const group = byOrigin.get(idx);
  const items = group?.items || [];
  const exact = items.find(c => (c.json.name || '').toString().trim().toLowerCase() === expected);
  return {
    json: {
      ...orig.json,
      _existingFileId: exact ? exact.json.id : '',
      _existingFileWebViewLink: exact ? exact.json.webViewLink : ''
    },
    binary: orig.binary,
    pairedItem: group ? group.firstCandidateIndex : 0
  };
});

// 'Pick Exact Attachment Match' only sets _existingFileWebViewLink from
// the Drive search result's own webViewLink -- that search response isn't
// guaranteed to include it either, so fall back to the same canonical
// Drive URL format built from the file id it always does return.
return $input.all().map(item => ({
  json: {
    webViewLink: item.json._existingFileWebViewLink
      || (item.json._existingFileId ? `https://drive.google.com/file/d/${item.json._existingFileId}/view?usp=drivesdk` : null)
  },
  pairedItem: item.pairedItem
}));

// Get previous node data -- drop tabName, it's routing metadata (which
// tab of the conversation sheet to write to) used by upstream/downstream
// nodes, not a column that belongs in the sheet itself.
const { tabName, ...previousData } = $('Message Already Logged?').item.json;

// When a message has no attachments, 'If Has Attachments'' false branch
// feeds this node the single ORIGINAL message item untouched -- NOT a
// Drive file result. That item's own `id` is the Outlook message id
// (e.g. 'AAMkADEzYjVk...'), so treating it as a fallback Drive file id
// synthesized a bogus drive.google.com link on every attachment-less row.
// Only ever read $input as Drive results when this message actually went
// through the attachment branch.
//
// 'Drive | Upload Attachment' has no explicit `fields` option, so its
// response isn't guaranteed to include webViewLink -- only `id` is
// guaranteed on any real Drive file response. Rebuild the same canonical
// URL Drive itself uses (confirmed identical to what the search path
// already returns) from the id whenever webViewLink itself didn't come
// back, instead of silently saving a blank link for a file that really is
// sitting in Drive.
const links = previousData.hasAttachments
  ? $input.all()
      .map(item => item.json.webViewLink
        || (item.json.id ? `https://drive.google.com/file/d/${item.json.id}/view?usp=drivesdk` : null))
      .filter(link => !!link)
  : [];

// Collect all webViewLinks -- named 'webViewLink1'/'webViewLink2'/... to
// match the conversation sheet's actual existing header columns. A prior
// version of this named them 'attachment1'/'attachment2', which didn't
// match any existing header, so autoMapInputData created a brand new
// 'attachment1' column instead of populating the real webViewLink1/2
// columns every other row (Gmail included) already uses.
const linkFields = {};
links.forEach((link, index) => {
  linkFields[`webViewLink${index + 1}`] = link;
});

return [
  {
    json: {
      ...previousData,
      ...linkFields
    }
  }
];
